import XCTest
@testable import ProsperApp

/// The codex app-server JSON schema generated by the pinned codex, with a validator for the
/// subset of draft-07 that `codex app-server generate-json-schema` emits and a checker for
/// direction-tagged transcripts. Test-only and hand-rolled: the package has no JSON Schema
/// dependency and doesn't need one.
///
/// Fixtures live in `Tests/Fixtures/codex/<version>/` (schema + recorded transcripts, one
/// `{"dir": "out"|"in", "frame": {…}}` per line, "out" = Prosper→codex). Re-record with
/// `scripts/record-codex-wire.py <codex>` on every pin bump: the directory is looked up by
/// `AgentController.codexVersion`, so a bump without it fails these tests.
///
/// Keywords: `$ref` (JSON pointer), type, enum, const, required, properties,
/// additionalProperties, items, allOf/anyOf/oneOf, minimum, minItems/maxItems. `oneOf` passes
/// on any matching branch, like `anyOf`: serde takes the first variant that decodes.
/// ponytail: `pattern` (3 uses) and `format` (int widths) are skipped; add when a bug hides there.
///
/// Strict mode (Prosper's frames): an object schema with `properties` and no
/// `additionalProperties` rejects other keys. codex's serde drops unknown fields silently, so
/// an unknown key is a setting codex never sees (W5: `thread/start.sandboxPolicy`). codex's
/// own frames are not strict: they carry keys the schema omits (top-level `emittedAtMs`).
struct CodexWireSchema: @unchecked Sendable {   // root is parsed once and never mutated
    let root: [String: Any]

    static let version = String(AgentController.codexVersion.dropFirst("rust-v".count))
    static let fixtures = URL(fileURLWithPath: #filePath).deletingLastPathComponent().deletingLastPathComponent()
        .appendingPathComponent("Fixtures/codex/\(version)", isDirectory: true)
    private static let loaded = Result { () throws -> CodexWireSchema in
        let data = try Data(contentsOf: fixtures.appendingPathComponent("codex_app_server_protocol.schemas.json"))
        return CodexWireSchema(root: try JSONSerialization.jsonObject(with: data) as? [String: Any] ?? [:])
    }
    static func shared() throws -> CodexWireSchema { try loaded.get() }

    typealias Transcript = [(out: Bool, frame: [String: Any])]

    /// A JSONL transcript; an unterminated last line (a log still being written) is skipped.
    static func transcript(_ text: String) throws -> Transcript {
        var lines = text.components(separatedBy: "\n")
        lines.removeLast()   // "" after the final newline, or the unterminated tail
        return try lines.filter { !$0.isEmpty }.map { line in
            let entry = try JSONSerialization.jsonObject(with: Data(line.utf8)) as? [String: Any] ?? [:]
            return (entry["dir"] as? String == "out", entry["frame"] as? [String: Any] ?? ["unparsed": line])
        }
    }

    static func transcript(named name: String) throws -> Transcript {
        try transcript(String(contentsOf: fixtures.appendingPathComponent("\(name).jsonl"), encoding: .utf8))
    }

    /// Every schema violation in `transcript`. A frame with a method is checked against its
    /// union's branch (`ClientRequest`/`ClientNotification` out, `ServerRequest`/
    /// `ServerNotification` in); a reply against the response type of the request it answers.
    func violations(in transcript: Transcript) -> [String] {
        var asked: [Bool: [String: String]] = [true: [:], false: [:]]   // by asker (out = Prosper)
        var found: [String] = []
        for (n, (out, frame)) in transcript.enumerated() {
            let method = frame["method"] as? String
            let id = frame["id"].map { "\($0)" }
            var problems: [String]
            if let method {
                let union = out ? (id == nil ? "ClientNotification" : "ClientRequest")
                                : (id == nil ? "ServerNotification" : "ServerRequest")
                if let id { asked[out]![id] = method }
                problems = branch(union, method).map {
                    errors(frame, $0, "", strict: out, allowed: ["jsonrpc", "params"])
                } ?? ["\(method) is not a \(union) method"]
            } else if let id {
                problems = reply(frame, to: asked[!out]!.removeValue(forKey: id), asker: out ? "ServerRequest" : "ClientRequest", strict: out)
            } else {
                problems = ["neither a method nor an id"]
            }
            found += problems.map { "#\(n + 1) \(out ? "out" : "in") \(method ?? "reply to \(id ?? "?")"): \($0)" }
        }
        return found
    }

    private func reply(_ frame: [String: Any], to method: String?, asker union: String, strict: Bool) -> [String] {
        guard let method else { return ["answers no pending request"] }
        if frame["error"] != nil {
            return errors(frame, def("#/definitions/JSONRPCError"), "", strict: strict, allowed: ["jsonrpc"])
        }
        guard let result = frame["result"] else { return ["reply to \(method) has neither result nor error"] }
        guard let type = responseType(union, method) else { return ["no response type for \(method)"] }
        let envelope = Set(frame.keys).subtracting(["jsonrpc", "id", "result"]).sorted()
        return errors(result, type, "result", strict: strict) + (strict ? envelope.map { "unknown key \($0)" } : [])
    }

    /// The `union` (e.g. "ClientRequest") branch whose `method` enum holds `method`.
    func branch(_ union: String, _ method: String) -> [String: Any]? {
        (def("#/definitions/\(union)")["oneOf"] as? [[String: Any]])?.first {
            (Self.prop($0, "method")?["enum"] as? [String])?.contains(method) == true
        }
    }

    /// `FooParams` → `FooResponse`, from the request branch's `params` ref.
    private func responseType(_ union: String, _ method: String) -> [String: Any]? {
        guard let ref = branch(union, method).flatMap({ Self.prop($0, "params")?["$ref"] as? String }),
              ref.hasSuffix("Params") else { return nil }
        let type = def(String(ref.dropLast("Params".count)) + "Response")
        return type.isEmpty ? nil : type
    }

    func def(_ ref: String) -> [String: Any] {
        ref.split(separator: "/").dropFirst().reduce(root as Any?) { ($0 as? [String: Any])?[String($1)] }
            as? [String: Any] ?? [:]
    }

    private static func prop(_ schema: [String: Any], _ key: String) -> [String: Any]? {
        (schema["properties"] as? [String: Any])?[key] as? [String: Any]
    }

    /// Violations of `value` against `schema`. `allowed`: keys a parent already declared (an
    /// object split across `properties` and a union, serde's flatten).
    func errors(_ value: Any, _ schema: [String: Any], _ path: String, strict: Bool,
                allowed: Set<String> = []) -> [String] {
        if let ref = schema["$ref"] as? String { return errors(value, def(ref), path, strict: strict, allowed: allowed) }
        let here = path.isEmpty ? "frame" : path
        if let problem = shallow(value, schema) { return ["\(here): \(problem)"] }
        var out: [String] = []
        if let array = value as? [Any] {
            if let min = schema["minItems"] as? Int, array.count < min { out.append("\(here): fewer than \(min) items") }
            if let max = schema["maxItems"] as? Int, array.count > max { out.append("\(here): more than \(max) items") }
            if let items = schema["items"] as? [String: Any] {
                for (i, v) in array.enumerated() { out += errors(v, items, "\(here)[\(i)]", strict: strict) }
            }
        }
        let props = schema["properties"] as? [String: Any] ?? [:]
        let unions = ["allOf", "anyOf", "oneOf"].compactMap { schema[$0] as? [[String: Any]] }
        if let object = value as? [String: Any] {
            for key in schema["required"] as? [String] ?? [] where object[key] == nil { out.append("\(here): missing \(key)") }
            for (key, v) in object.sorted(by: { $0.key < $1.key }) {
                if let p = props[key] as? [String: Any] {
                    out += errors(v, p, "\(here).\(key)", strict: strict)
                } else if allowed.contains(key) || !unions.isEmpty {
                    continue   // the parent or the union branch owns it
                } else if let extra = schema["additionalProperties"] as? [String: Any] {
                    out += errors(v, extra, "\(here).\(key)", strict: strict)
                } else if schema["additionalProperties"] as? Bool == false
                            || (strict && !props.isEmpty && schema["additionalProperties"] == nil) {
                    out.append("\(here): unknown key \(key)")
                }
            }
        }
        let inherited = allowed.union(props.keys)
        for (kind, branches) in zip(["allOf", "anyOf", "oneOf"].filter { schema[$0] != nil }, unions) {
            let results = branches.map { errors(value, $0, path, strict: strict, allowed: inherited) }
            if kind == "allOf" { out += results.joined(); continue }
            guard !results.contains(where: \.isEmpty) else { continue }
            // Report the branch whose type and tag (single-value enum: `type`, `method`) fit.
            let fitting = zip(branches, results).filter { branch, _ in
                let b = (branch["$ref"] as? String).map(def) ?? branch
                return (b["type"].map { shallow(value, ["type": $0]) == nil } ?? true) && ((value as? [String: Any]) ?? [:]).allSatisfy { key, v in
                    Self.prop(b, key).map { shallow(v, $0) == nil || ($0["enum"] as? [Any])?.count != 1 } ?? true
                }
            }
            if let best = fitting.min(by: { $0.1.count < $1.1.count }) { out += best.1 }
            else { out.append("\(here): \(Self.text(value)) matches no \(kind) branch of \(schema["title"] as? String ?? "?")") }
        }
        return out
    }

    /// type / enum / const / minimum of `value` itself, nil when it passes.
    private func shallow(_ value: Any, _ schema: [String: Any]) -> String? {
        if let t = schema["type"] {
            let types = t as? [String] ?? [t as? String ?? ""]
            if !types.contains(where: { Self.isType(value, $0) }) { return "\(Self.text(value)) is not \(types.joined(separator: "|"))" }
        }
        if let options = schema["enum"] as? [Any], !options.contains(where: { Self.same($0, value) }) {
            return "\(Self.text(value)) is not one of \(Self.text(options))"
        }
        if let c = schema["const"], !Self.same(c, value) { return "\(Self.text(value)) is not \(Self.text(c))" }
        if let min = schema["minimum"] as? Double, let n = value as? NSNumber, !Self.isBool(n), n.doubleValue < min {
            return "\(n) is below \(min)"
        }
        return nil
    }

    private static func isBool(_ v: Any) -> Bool {
        (v as? NSNumber).map { CFGetTypeID($0) == CFBooleanGetTypeID() } ?? false
    }

    private static func isType(_ v: Any, _ type: String) -> Bool {
        switch type {
        case "null": return v is NSNull
        case "boolean": return isBool(v)
        case "integer": return (v as? NSNumber).map { !isBool($0) && $0.doubleValue.rounded() == $0.doubleValue } ?? false
        case "number": return v is NSNumber && !isBool(v)
        case "string": return v is String
        case "array": return v is [Any]
        case "object": return v is [String: Any]
        default: return false
        }
    }

    private static func same(_ a: Any, _ b: Any) -> Bool {
        isBool(a) == isBool(b) && (a as AnyObject).isEqual(b)
    }

    static func text(_ v: Any) -> String {
        (try? JSONSerialization.data(withJSONObject: v, options: [.fragmentsAllowed, .sortedKeys]))
            .map { String(decoding: $0, as: UTF8.self) } ?? "\(v)"
    }
}

/// codex's wire, checked against the schema of the pinned codex: recorded real-codex
/// transcripts, the frame shapes behind the audited wire bugs (#150 W1–W8), and the Wire
/// method table. What Prosper actually sends is checked by `CodexHarnessE2ETests`, whose mock
/// logs both directions and validates them here on every test's teardown.
final class CodexWireSchemaTests: XCTestCase {
    private static let recordings = ["plain-turn", "approval", "interrupt", "failed-turn"]

    private func violations(_ frames: [(Bool, [String: Any])]) throws -> [String] {
        try CodexWireSchema.shared().violations(in: frames.map { (out: $0.0, frame: $0.1) })
    }

    /// A pin bump without re-recording fails here, not on a user's machine.
    func testFixturesExistForThePinnedCodex() throws {
        for name in ["codex_app_server_protocol.schemas.json"] + Self.recordings.map({ "\($0).jsonl" }) {
            XCTAssertTrue(FileManager.default.fileExists(atPath: CodexWireSchema.fixtures.appendingPathComponent(name).path),
                          "no \(name) for codex \(CodexWireSchema.version): run scripts/record-codex-wire.py")
        }
        XCTAssertFalse(try CodexWireSchema.shared().def("#/definitions/ClientRequest").isEmpty)
    }

    /// Both directions of every recording match the schema, and the recordings hold what the
    /// harness tests stand on: each scenario's terminal turn status and codex's real ids.
    func testRecordedTranscriptsMatchTheSchema() throws {
        for name in Self.recordings {
            let transcript = try CodexWireSchema.transcript(named: name)
            XCTAssertGreaterThan(transcript.filter(\.out).count, 3, name)
            XCTAssertEqual(try CodexWireSchema.shared().violations(in: transcript), [], name)
        }
        let statuses = try Self.recordings.map { name in
            try CodexWireSchema.transcript(named: name)
                .compactMap { $0.frame["method"] as? String == "turn/completed" ? $0.frame : nil }
                .map { (($0["params"] as? [String: Any])?["turn"] as? [String: Any])?["status"] as? String }
        }
        XCTAssertEqual(statuses, [["completed"], ["completed"], ["interrupted"], ["failed"]])
    }

    /// W3/W4 against real shapes: the recorded notifications map to the events the controller
    /// needs, with the turn id from `turn.id` (never a fabricated or empty one).
    func testRecordedNotificationsMapToHarnessEvents() throws {
        func events(_ name: String) throws -> (turnID: String, events: [HarnessEvent]) {
            let transcript = try CodexWireSchema.transcript(named: name)
            let turnID = try XCTUnwrap(transcript.lazy.compactMap {
                (($0.frame["result"] as? [String: Any])?["turn"] as? [String: Any])?["id"] as? String
            }.first, "\(name): no turn/start result")
            let events = transcript.filter { !$0.out && $0.frame["id"] == nil }.flatMap {
                CodexHarness.mapNotification(method: $0.frame["method"] as? String ?? "",
                                             params: $0.frame["params"] as? [String: Any] ?? [:])
            }
            return (turnID, events)
        }
        let plain = try events("plain-turn")
        XCTAssertTrue(plain.events.contains { if case .turnStarted(let t) = $0 { return t.raw == plain.turnID }; return false },
                      "\(plain.events)")
        XCTAssertTrue(plain.events.contains { if case .textDelta(_, _, "Hello") = $0 { return true }; return false }, "\(plain.events)")
        XCTAssertTrue(plain.events.contains { if case .usage(let u) = $0 { return u.inputTokens == 10 && u.outputTokens == 5 }; return false },
                      "\(plain.events)")
        XCTAssertTrue(plain.events.contains { if case .turnCompleted(let t, .completed) = $0 { return t.raw == plain.turnID }; return false },
                      "\(plain.events)")

        let approval = try events("approval")
        XCTAssertTrue(approval.events.contains { if case .toolCallCompleted(let call) = $0 { return call.status == .succeeded }; return false },
                      "\(approval.events)")
        let interrupt = try events("interrupt")
        XCTAssertTrue(interrupt.events.contains { if case .toolCallStarted = $0 { return true }; return false }, "\(interrupt.events)")
        XCTAssertTrue(interrupt.events.contains { if case .turnCompleted(let t, .aborted) = $0 { return t.raw == interrupt.turnID }; return false },
                      "\(interrupt.events)")
        let failed = try events("failed-turn")
        XCTAssertTrue(failed.events.contains {
            if case .turnCompleted(let t, .failed(let message)) = $0 { return t.raw == failed.turnID && message.contains("fake endpoint") }
            return false
        }, "\(failed.events)")
    }

    /// The audited wire bugs as the frames they put on the wire: each is a violation, and its
    /// fix passes. Pins the validator; `CodexHarnessE2ETests` pins that Prosper sends the fix.
    func testValidatorFlagsTheAuditedWireBugs() throws {
        let interrupt: [String: Any] = ["threadId": "t", "turnId": "u"]
        let text: [String: Any] = ["type": "text", "text": "hi"]
        let bad: [(String, [(Bool, [String: Any])], String)] = [
            ("W1 interrupt as notification", [(true, ["method": "turn/interrupt", "params": interrupt])],
             "turn/interrupt is not a ClientNotification method"),
            ("W2 steer as notification", [(true, ["method": "turn/steer", "params": ["threadId": "t", "expectedTurnId": "u", "input": [text]]])],
             "turn/steer is not a ClientNotification method"),
            ("W2 steer without expectedTurnId", [(true, ["id": 1, "method": "turn/steer", "params": ["threadId": "t", "turnId": "u", "input": [text]]])],
             "missing expectedTurnId"),
            ("W5 sandboxPolicy on thread/start", [(true, ["id": 1, "method": "thread/start", "params": ["sandboxPolicy": ["type": "readOnly"]]])],
             "unknown key sandboxPolicy"),
            ("W5 bad sandbox mode", [(true, ["id": 1, "method": "thread/start", "params": ["sandbox": "workspaceWrite"]])],
             "is not one of"),
            ("W6 image by path", [(true, ["id": 1, "method": "turn/start", "params": ["threadId": "t", "input": [["type": "image", "path": "/a.png"]]]])],
             "unknown key path"),
            ("W7 permissions decision", [(false, ["id": 0, "method": "item/permissions/requestApproval", "params": [:]]),
                                         (true, ["id": 0, "result": ["decision": "accept"]])],
             "out reply to 0: result: missing permissions"),   // the reply's own violation, not the request's
            ("W8 made-up decline result", [(false, ["id": 0, "method": "mcpServer/elicitation/request", "params": [:]]),
                                           (true, ["id": 0, "result": ["decision": "decline"]])],
             "missing action"),
        ]
        for (name, frames, needle) in bad {
            let found = try violations(frames)
            XCTAssertTrue(found.contains { $0.contains(needle) }, "\(name): want \"\(needle)\" in \(found)")
        }
        let good: [(String, [(Bool, [String: Any])])] = [
            ("W1", [(true, ["jsonrpc": "2.0", "id": 1, "method": "turn/interrupt", "params": interrupt])]),
            ("W2", [(true, ["id": 1, "method": "turn/steer", "params": ["threadId": "t", "expectedTurnId": "u", "input": [text]]])]),
            ("W5", [(true, ["id": 1, "method": "thread/start", "params": ["sandbox": "workspace-write", "config": ["bypass_hook_trust": true]]]),
                    (true, ["id": 2, "method": "turn/start", "params": ["threadId": "t", "input": [text], "sandboxPolicy":
                        ["type": "workspaceWrite", "writableRoots": ["/w"], "networkAccess": false]]])]),
            ("W6", [(true, ["id": 1, "method": "turn/start", "params": ["threadId": "t", "input": [["type": "localImage", "path": "/a.png"]]]])]),
            ("W7", [(false, ["id": 0, "method": "item/permissions/requestApproval", "params": [:]]),
                    (true, ["id": 0, "result": ["permissions": ["network": ["enabled": true]], "scope": "session"]])]),
            ("W8", [(false, ["id": 0, "method": "mcpServer/elicitation/request", "params": [:]]),
                    (true, ["id": 0, "error": ["code": -32601, "message": "not supported"]])]),
        ]
        for (name, frames) in good {
            // Server request params are left empty above; only the client side is under test.
            XCTAssertEqual(try violations(frames).filter { $0.contains(" out ") || !$0.contains(" in ") }, [], name)
        }
    }

    /// Replaces scripts/verify-codex-wire.sh: every method name in `CodexHarness.Wire` is in
    /// the schema, in the union its direction needs (requests where codex expects requests).
    func testWireMethodsAreInTheirUnions() throws {
        let source = try String(contentsOf: URL(fileURLWithPath: #filePath).deletingLastPathComponent()
            .deletingLastPathComponent().deletingLastPathComponent()
            .appendingPathComponent("Sources/ProsperApp/Harness/CodexHarness.swift"), encoding: .utf8)
        let wire = try XCTUnwrap(source.range(of: "private enum Wire {").map { source[$0.upperBound...] })
        let constants = try NSRegularExpression(pattern: #"static let (\w+) = "([^"]+)""#)
            .matches(in: String(wire), range: NSRange(wire.startIndex..., in: wire))
            .map { m in (Substring(wire)[Range(m.range(at: 1), in: wire)!], String(wire[Range(m.range(at: 2), in: wire)!])) }
        XCTAssertGreaterThan(constants.count, 20)
        let requests: Set<Substring> = ["initialize", "threadStart", "threadResume", "threadFork", "turnStart", "turnSteer", "turnInterrupt"]
        let schema = try CodexWireSchema.shared()
        for (name, method) in constants {
            let union = requests.contains(name) ? "ClientRequest" : name == "initialized" ? "ClientNotification"
                : name.hasSuffix("Approval") ? "ServerRequest" : "ServerNotification"
            XCTAssertNotNil(schema.branch(union, method), "Wire.\(name) = \(method) is not a \(union) method in codex \(CodexWireSchema.version)")
        }
    }
}
